INSERT INTO `projects` (`id`, `title`, `description`, `author`, `email`, `image_url`, `status`, `created_at`, `updated_at`, `topic`, `project_type`, `media_url`, `before_image_url`, `after_image_url`, `author_role`, `project_date`, `source_info`, `tags_json`, `gallery_json`) VALUES
(3, 'Меткий стрелок', 'Учащиеся средней школы № 133 г. Минска имени Д. Г. Фроликова посетили мероприятие «Юный стрелок», где смогли познакомиться с основами стрелкового дела, проверить свою меткость и проявить внимательность и выдержку.\r\n\r\nМероприятие стало отличной возможностью получить новые знания, попробовать свои силы и провести время с пользой!', 'Владислав', 'vladlol@gmail.com', '/uploads/1792401899157-chwedyqt.jpg', 'approved', '2026-10-19 09:24:59', '2026-10-19 09:25:04', 'people', 'photo', NULL, NULL, NULL, 'Учащийся', '2026-04-07', NULL, '[\"школа\",\"воспоминания\",\"традиции\",\"люди\",\"стрелок\"]', '[\"/uploads/1792401899188-4c3ywq17.jpg\",\"/uploads/1792401899218-wmuo90sh.jpg\"]'),
(22, 'музей авиации', 'Учащиеся средней школы № 133 г. Минска имени Д. Г. Фроликова посетили музей авиации, где познакомились с историей развития авиации, узнали больше о легендарных воздушных судах и достижениях авиастроения.\r\n\r\nЭкскурсия подарила ребятам новые знания, яркие впечатления и возможность прикоснуться к удивительному миру неба!', 'Владислав', 'vladkek@gmail.com', '/uploads/1792404112405-tahekib2.jpg', 'approved', '2026-10-19 10:01:52', '2026-10-19 10:02:22', 'places', 'photo', NULL, NULL, NULL, 'Учащийся', '2026-04-16 - 2026-04-17', NULL, '[\"школа\",\"люди\",\"воспоминания\",\"памятное-место\",\"Авиация\"]', '[\"/uploads/1792404112425-zr8h9cz4.jpg\",\"/uploads/1792404112454-4n8hv5i9.jpg\",\"/uploads/1792404112462-ljl5cpvd.jpg\",\"/uploads/1792404112513-jnk2wbpa.jpg\",\"/uploads/1792404112545-7qs6qg0o.jpg\"]'),
(23, 'Площадь Победы -память, которая живёт в наших сердцах', 'Учащиеся средней школы № 133 г. Минска имени Д. Г. Фроликова посетили площадь Победы -одно из самых значимых и памятных мест столицы Беларуси.\r\nРебята познакомились с историей мемориального комплекса, узнали больше о подвиге советских солдат и героизме людей, которые сражались за свободу и независимость нашей Родины. Особое внимание было уделено Вечному огню - символу вечной памяти и благодарности тем, кто отдал свою жизнь за мирное будущее.\r\nТакие посещения помогают молодому поколению сохранять историческую память, воспитывают уважение к подвигу предков и напоминают о важности мира, единства и патриотизма.', 'Владислав', 'vladkek@gmail.com', '/uploads/1792404478460-khnha6cd.jpg', 'approved', '2026-10-19 10:07:59', '2026-10-19 10:08:06', 'places', 'photo', NULL, NULL, NULL, 'Учащийся', '2026-04-14', NULL, '[\"школа\",\"воспоминания\",\"традиции\",\"люди\",\"история\",\"ПлощадьПобеды\",\"ИсторическаяПамять\",\"ПатриотическоеВоспитание\",\"МыПомним\"]', '[\"/uploads/1792404478489-dtsnsoem.jpg\",\"/uploads/1792404478507-wna0k4re.jpg\",\"/uploads/1792404478542-p9eny9gn.jpg\",\"/uploads/1792404478560-jglonk10.jpg\",\"/uploads/1792404479006-9o8j4iqb.jpg\"]'),
(24, 'Торжественное вступление в военно-патриотический класс', '16 декабря состоялось торжественное мероприятие, посвящённое вступлению учащихся в военно-патриотический класс. Это важный и ответственный шаг для ребят, которые стремятся стать достойными гражданами своей страны, чтить её историю и сохранять традиции патриотизма.\r\n\r\nВступление в военно-патриотический класс символизирует готовность проявлять ответственность, дисциплину, уважение к старшим и верность своей Родине. Участие в жизни класса поможет учащимся развивать силу духа, командный дух, формировать активную гражданскую позицию и узнавать больше о героическом прошлом Беларуси.\r\n\r\nПусть этот день станет началом большого пути, наполненного новыми знаниями, достижениями и добрыми делами во имя родной страны!', 'Владислав', 'vladkek@gmail.com', '/uploads/1792404832094-9dw4teds.jpg', 'approved', '2026-10-19 10:13:52', '2026-10-19 10:20:48', 'school', 'photo', NULL, NULL, NULL, 'Учащийся', '2025-12-16', NULL, '[\"школа\",\"воспоминания\",\"люди\",\"традиции\",\"ВоенноПатриотическийКласс\",\"ПатриотическоеВоспитание\"]', '[\"/uploads/1792404832097-eh91lpnl.jpg\",\"/uploads/1792404832098-jzwz96gn.jpg\",\"/uploads/1792404832098-vlfwmyda.jpg\",\"/uploads/1792404832098-54e1zjil.jpg\",\"/uploads/1792404832099-eyzy07lh.jpg\",\"/uploads/1792404832105-zjfobrem.jpg\",\"/uploads/1792404832107-7fq4o35l.jpg\",\"/uploads/1792404832108-bi2v6wqe.jpg\",\"/uploads/1792404832110-brjh579m.jpg\"]'),
(27, 'Монумент победы', 'Время меняется, город развивается, но память о подвиге героев остаётся неизменной. Монумент Победы в Минске - символ мужества, стойкости и благодарности тем, кто подарил нам мирное небо над головой.\r\n\r\nПомним прошлое, ценим настоящее и сохраняем историю для будущих поколений.', 'Владислав', 'vladkek@gmail.com', '/uploads/1792406307055-jqvppoo1.jpeg', 'approved', '2026-10-19 10:38:27', '2026-10-19 10:38:37', 'places', 'video', '/uploads/1792406307055-6hk0e0i3.mp4', NULL, NULL, 'Учащийся', '2025-11-10', NULL, '[\"школа\",\"памятное-место\",\"традиции\",\"история\",\"люди\"]', '[]'),
(28, 'Музейная экспозиция', 'Ученица средней школы № 133 г. Минска имени Д. Г. Фроликова подготовила видеоролик о музейной экспозиции школы. В своём видео она познакомила зрителей с экспонатами, хранящими память о важных исторических событиях, людях и традициях.\r\n\r\nШкольный музей - это место, где прошлое встречается с настоящим, а история оживает через подлинные свидетельства времени. 🇧🇾', 'Владислав', 'vladkek@gmail.com', '/uploads/1792406803407-eqt01v7r.png', 'approved', '2026-10-19 10:46:44', '2026-10-19 10:46:48', 'school', 'video', '/uploads/1792406803410-kx2zrmdq.mp4', NULL, NULL, 'Учащийся', '2025-07-16', NULL, '[\"школа\",\"традиции\",\"история\",\"люди\",\"памятное-место\"]', '[]'),
(29, 'Буктрелер: Василь Быков, В списках не значился', 'Буктрелер: Василь Быков, В списках не значился', 'Владислав', 'vladkek@gmail.com', '/uploads/1792407618336-y8nt2vf4.png', 'approved', '2026-10-19 11:00:19', '2026-10-19 11:00:22', 'creative', 'video', '/uploads/1792407618336-of0ajbdo.mp4', NULL, NULL, 'Учащийся', '2025-03-29', NULL, '[\"воспоминания\",\"история\",\"Буктрелер\",\"ВасильБыков\"]', '[]');
